// Parse incoming signal
const items = $input.all();
const signals = [];

for (const item of items) {
  const body = item.json.body || item.json;

  signals.push({
    json: {
      session_id: body.session_id || body.user_session_id,
      user_id: body.user_id || null,
      event_name: body.event_name || body.event,
      city: body.city || null,
      state: body.state || null,
      vertical: body.vertical || 'solar',
      audience: body.audience || 'b2c',
      company_id: body.company_id || null,
      timestamp: body.timestamp || new Date().toISOString()
    }
  });
}

return signals;

// Calculate intent score with 7-day half-life decay
const items = $input.all();
const results = [];

// Event weights
const EVENT_WEIGHTS = {
  page_view: 1,
  company_profile_view: 3,
  review_read: 2,
  roi_expand: 8,
  compare_view: 10,
  cta_click: 5,
  banner_click: 3,
  wizard_start: 12,
  wizard_complete: 25,
  whatsapp_click: 30,
  review_submit: 5
};

const HALF_LIFE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
const now = Date.now();

for (const item of items) {
  const signal = item.json;
  const sessionHistory = item.json._history || [];

  // Build signals map
  const signalsMap = {};

  // Add existing signals from history
  if (sessionHistory.length > 0 && sessionHistory[0].signals) {
    const existing = sessionHistory[0].signals;
    Object.assign(signalsMap, existing);
  }

  // Add new signal
  const eventName = signal.event_name;
  signalsMap[eventName] = (signalsMap[eventName] || 0) + 1;

  // Calculate weighted score with decay
  let totalScore = 0;
  const lastSignalAt = sessionHistory.length > 0 ? new Date(sessionHistory[0].last_signal_at).getTime() : now;
  const daysSinceLast = (now - lastSignalAt) / (1000 * 60 * 60 * 24);

  for (const [event, count] of Object.entries(signalsMap)) {
    const weight = EVENT_WEIGHTS[event] || 1;
    // Apply decay based on how old the signal cluster is
    const decay = Math.pow(0.5, daysSinceLast / 7);
    totalScore += weight * count * decay;
  }

  // Add weight for the new event itself (no decay)
  const newEventWeight = EVENT_WEIGHTS[eventName] || 1;
  totalScore += newEventWeight;

  // Clamp to 0-100
  totalScore = Math.min(100, Math.max(0, totalScore));

  // Classify intent level
  let intentLevel;
  if (totalScore >= 80) intentLevel = 'declared';
  else if (totalScore >= 50) intentLevel = 'immediate';
  else if (totalScore >= 30) intentLevel = 'boiling';
  else if (totalScore >= 15) intentLevel = 'hot';
  else if (totalScore >= 5) intentLevel = 'warm';
  else intentLevel = 'cold';

  // Calculate confidence based on signal count
  const signalCount = Object.values(signalsMap).reduce((a, b) => a + b, 0);
  const confidence = Math.min(0.95, 0.3 + (signalCount * 0.05));

  results.push({
    json: {
      session_id: signal.session_id,
      user_id: signal.user_id,
      city: signal.city,
      state: signal.state,
      vertical: signal.vertical,
      audience: signal.audience,
      company_id: signal.company_id,
      signals: signalsMap,
      intent_score: Math.round(totalScore * 100) / 100,
      intent_level: intentLevel,
      confidence: Math.round(confidence * 100) / 100,
      last_signal_at: new Date().toISOString(),
      previous_level: sessionHistory.length > 0 ? sessionHistory[0].intent_level : null,
      level_changed: sessionHistory.length > 0 && sessionHistory[0].intent_level !== intentLevel,
      created_at: new Date().toISOString()
    }
  });
}

return results;
